// const cheerio = require('cheerio')

module.exports = (url, protocol) => new Promise((resolve, reject) => {
  protocol = protocol || 'https'
  const protocolMethod = require(protocol)
  url = url || 'ebay-kleinanzeigen.de/s-86150/l7522r10'
  // console.log(`url: ${url}, protocol: ${protocol}`)
  // console.log(`${protocol}://${url}`)
  return protocolMethod.get(`${protocol}://${url}`, (res) => {
    let html = ''
    // console.log('statusCode:', res.statusCode)
    // console.log('headers:', res.headers)

    res.on('data', (chunk) => {
      html += chunk
      console.log('data received')
    })
    res.on('end', () => {
      // const $ = cheerio.load(html)
      // console.log(html)
      resolve(html)
    })
  }).on('error', (e) => {
    reject(new Error(e))
  })
})
